#pragma once
#include "GUI.h"
#include "Interfaces.h"
void CWindow::SetPosition(int x, int y)
{
	m_x = x; m_y = y;
}
void CWindow::SetSize(int w, int h)
{
	m_iWidth = w;
	m_iHeight = h;
}
void CWindow::SetTitle(std::string title)
{
	Title = title;
}
void CWindow::RegisterTab(CTab* Tab)
{
	if (Tabs.size() == 0)
	{
		SelectedTab = Tab;
	}
	Tab->parent = this;
	Tabs.push_back(Tab);
}
RECT CWindow::GetDragArea()
{
	RECT client;
	client.left = m_x + 8;
	client.top = m_y + 1 + 30;
	client.right = m_iWidth - 4 - 12;
	client.bottom = 29;
	return client;
}
RECT CWindow::GetClientArea()
{
	RECT client;
	client.left = m_x + 8;
	client.top = m_y + 1 + 27;
	client.right = m_iWidth - 4 - 12;
	client.bottom = m_iHeight - 2 - 8 - 26;
	return client;
}
RECT CWindow::GetTabArea()
{
	RECT client;
	client.left = m_x + 8;
	client.top = m_y + 1 + 27;
	client.right = m_iWidth - 4 - 12;
	client.bottom = 29;
	return client;
}
void CWindow::Open()
{
	m_bIsOpen = true;
}
void CWindow::Close()
{
	m_bIsOpen = false;
}
void CWindow::Toggle()
{
	m_bIsOpen = !m_bIsOpen;
	static ConVar * cvar = interfaces::cvar->FindVar("cl_mouseenable");
	if (m_bIsOpen)
	{
		cvar->SetValue(0);
	}
	else
	{
		cvar->SetValue(1);
	}
}
CControl* CWindow::GetFocus()
{
	return FocusedControl;
}
// TABS ---------------------------------------------------------------------------------------------------
void CTab::SetTitle(std::string name)
{
	Title = name;
}
void CTab::RegisterControl(CControl* control)
{
	control->parent = parent;
	Controls.push_back(control);
}




























































































































































